     * @alias toThrow
     */
    toThrowError(expected?: unknown): void;

    /**
     * Asserts that a value matches a regular expression or includes a substring.
     *
     * @example
     * expect("dog").toMatch(/dog/);
     * expect("dog").toMatch("og");
